{"language":"js","summary":"Search the working directory for definitions of a function named add","code":"const pats = [
  String.raw`\bfn\s+add\b`,
  String.raw`\bfunction\s+add\b`,
  String.raw`\bdef\s+add\b`,
  String.raw`\bfunc\s+(\([^)]*\)\s*)?add\b`,
  String.raw`\b(const|let|var)\s+add\s*=`,
];
const res = await parallel([
  ...pats.map(p => () => tool.grep({ pattern: p, path: "." }).catch(e => ({ text: "ERR " + e.message }))),
  () => Bun.$`pwd`.text(),
]);
print(res.map(r => typeof r === "string" ? r : r.text).join("\n---\n"));"}
